import math
from itertools import permutations

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def is_cool_backtracking(n):
    """
    Checks if n is a cool integer using backtracking.
    Returns (True, permutation) if cool, (False, None) otherwise.
    """

    # State: (current_permutation, used_numbers_set, current_sum)

    def solve(path, used, current_sum):
        if len(path) == n:
            # Successfully found a permutation of length n
            return path

        for x in range(1, n + 1):
            if x not in used:
                next_sum = current_sum + x

                if not is_perfect_square(next_sum):
                    # Constraint satisfied, proceed deeper
                    new_path = path + [x]
                    new_used = used | {x}

                    result = solve(new_path, new_used, next_sum)
                    if result is not None:
                        return result

        # Backtrack
        return None

    # Start the search
    permutation = solve([], set(), 0)

    if permutation:
        return True, permutation
    else:
        return False, None

