import math
from itertools import permutations

def is_square(k):
    if k < 0:
        return False
    sqrt_k = int(math.isqrt(k))
    return sqrt_k * sqrt_k == k

def is_cool(n):
    if n == 0:
        return False

    # Necessary condition check (S_n must not be a square)
    S_n = n * (n + 1) // 2
    if is_square(S_n):
        return False

    # Backtracking search for a cool permutation
    elements = list(range(1, n + 1))

    def backtrack(current_sum, remaining_elements):
        if not remaining_elements:
            # We successfully constructed a permutation
            return True

        for i in range(len(remaining_elements)):
            x = remaining_elements[i]
            next_sum = current_sum + x

            if not is_square(next_sum):
                new_remaining = remaining_elements[:i] + remaining_elements[i+1:]
                if backtrack(next_sum, new_remaining):
                    return True

        return False

    # Start the search. The first element x1 must not be a square.
    # Since n >= 2 (as n=1 fails), we check all possibilities for x1.
    for x1 in elements:
        if not is_square(x1):
            remaining = elements[:elements.index(x1)] + elements[elements.index(x1)+1:]
            if backtrack(x1, remaining):
                return True

    return False

