test_n_values = [2, 3, 4, 5, 6, 7, 9, 15, 40, 48, 50, 100]

results = {}
for n in test_n_values:
    if n == 1:
        results[n] = "Known Non-Cool (S_1=1)"
        continue

    S_n = n * (n + 1) // 2
    if is_square(S_n):
        results[n] = f"Known Non-Cool (S_{n}={S_n}=Square)"
    else:
        is_c = is_cool(n)
        results[n] = "Cool" if is_c else "Non-Cool (Counterexample found)"

print("--- Test Results ---")
for n, result in results.items():
    print(f"n={n}: {result}")
